// Function to reverse a string
void reverseString(char *inputString) {
    int length = strlen(inputString);
    int start = 0;
    int end = length - 1;
    char temp;

    // Reverse the string in place
    while (start < end) {
        temp = inputString[start];
        inputString[start] = inputString[end];
        inputString[end] = temp;
        start++;
        end--;
    }
}

int main() {
    // Initialize a string with a hidden message in variable names
    char thIsIsASecretMessage[] = "Hello, World!";

    // Print the original string
