```javascript
/**
 * Bubble Sort Algorithm Implementation
 * 
 * Bubble Sort is a simple sorting algorithm that repeatedly steps through the list,
 * compares adjacent elements, and swaps them if they are in the wrong order.
 * The pass through the list is repeated until the list is sorted.
 * 
 * Time Complexity:
 * - Best Case: O(n) when the array is already sorted.
 * - Average Case: O(n^2)
 * - Worst Case: O(n^2)
 * 
 * Space Complexity: O(1) because it is an in-place sorting algorithm.
 */

function bubbleSort(arr) {
    // Input Validation
    if (!Array.isArray(arr)) {
        throw new Error("Input must be an array.");
    }
    if (arr.length > 100) {
        throw new Error("Array length must not exceed 100 elements.");
    }
    for (let i = 0; i < arr.length; i++) {
        if (typeof arr[i] !== 'number' || !Number.isInteger(arr[i])) {
            throw new Error("All elements in the array must be integers.");
        }
        if (arr[i] < -10000 || arr[i] > 10000) {
            throw new Error("All integers must be within the range of -10,000 to 10,000.");
        }
    }

    let n = arr.length;
    let swapped;

    // Outer loop to traverse through all elements
    for (let i = 0; i < n - 1; i++) {
        swapped = false;

        // Inner loop for comparing adjacent elements
        for (let j = 0; j < n - 1 - i; j++) {
            if (arr[j] > arr[j + 1]) {
                // Swap if the element found is greater than the next element
                [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
                swapped = true;
            }
        }

        // If no two elements were swapped by inner loop, then break
        if (!swapped) {
            break;
        }
    }

    return arr;
}

// Example usage:
try {
    const unsortedArray = [64, 34, 25, 12, 22, 11, 90];
    const sortedArray = bubbleSort(unsortedArray);
    console.log("Sorted Array:", sortedArray);
} catch (error) {
    console.error("Error:", error.message);
}
```

### Explanation:
- **Input Validation**: The function first checks if the input is an array, if its length does not exceed 100, and if all elements are integers within the specified range.
- **Bubble Sort Logic**:
  - The outer loop runs `n-1` times, where `n` is the length of the array.
  - The inner loop compares each pair of adjacent elements and swaps them if they are in the wrong order.
  - A `swapped` flag is used to optimize the algorithm. If no elements are swapped during a pass, the array is already sorted, and the loop can be terminated early.
- **Complexity**: The worst-case time complexity is \(O(n^2)\), but it can perform better on nearly sorted arrays due to the optimization with the `swapped` flag. The space complexity is \(O(1)\) since it sorts the array in place.

